const c_dot_0 = ui.must(await ui.quickAdd(pg_vic, {"name": "Dot", "amount": "25.00"}));
const p_dot = await ui.personId(pg_vic, "Dot");
await ui.showRetired(pg_vic, true);
expect(await ui.addClaim(pg_vic, p_ada, {"amount": "20.00", "note": "n"})).toBeNull();
expect(await ui.holdClaim(pg_vic, c_ada_0)).toBe(true);
expect(await ui.bulkRetire(pg_vic, [p_dot, p_cam], "2026-03-09")).toBe(2);
await ui.showRetired(pg_vic, true);
expect(await ui.holdClaim(pg_vic, c_ada_0)).toBe(true);
expect(await ui.statement(pg_vic, p_dot)).toBe(true);
await ui.refresh(pg_vic);
await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
